export function todosMutators(client: MutationTarget, notify: () => void = () => undefined): TodosMutators {
  return {
    create(id: string, values: TodosMutation): void {
      client.create(todosTable, rowId(id), wire(values), txnId(`create-${id}`));
      notify();
    },
    update(id: string, values: TodosMutation): void {
      client.update(todosTable, rowId(id), wire(values), txnId(`update-${id}-${crypto.randomUUID()}`));
      notify();
    },
    delete(id: string): void {
      client.delete(todosTable, rowId(id), txnId(`delete-${id}-${crypto.randomUUID()}`));
      notify();
    },
  };
}

export function useTodos(source: WeftSource, orderBy: TodosField = "id"): readonly TodosRow[] {
  return useWeftRows(source, todosQuery(orderBy), decodeTodos);
}

export type TodosQueryBuilder = (statement: ScopedRowQuery<Database, "todos">) => ScopedRowQuery<Database, "todos">;

/**
 * A statement over `todos`, scoped and selecting `id` before the callback sees it. Chain
 * `where`, `orderBy`, `limit`, and `offset` onto it. Scoping is not the caller's to get
 * right: one database file holds every scope, and a row id is unique only within its
 * collection, so an unscoped statement can match another scope's row.
 */
export function todosSqlQuery(scopeId: string, build: TodosQueryBuilder = (statement) => statement): ReactiveSqlQuery {
  const scoped = weftStatements.selectFrom("todos").select("id").where("scope_id", "=", scopeId);
  return reactiveSqlQuery({ tableName: todosTable, query: build(scoped) });
}

export function useTodosQuery(source: WeftSqlSource, build?: TodosQueryBuilder): readonly TodosRow[] {
  return useWeftSqlRows(source, todosSqlQuery(source.scopeId, build), decodeTodos);
}

/** A rank that puts a new row after everything in `rows`, which must be ordered by rank. */
export function nextTodosRank(rows: readonly TodosRow[], device: DeviceId): string {
  const rankOf = (row: TodosRow | undefined) => (row === undefined ? null : rankString(String(row["rank"])));
  return rankBetween(rankOf(rows.at(-1)), null, device);
}

/**
 * Moves the row at `index` one place. Reordering writes one field — the row's new rank,
 * taken from between the two rows it lands between — so nothing below it is renumbered and
 * two devices reordering at once do not undo each other.
 */
export function moveTodos(
  mutators: TodosMutators,
  rows: readonly TodosRow[],
  index: number,
  direction: "up" | "down",
  device: DeviceId,
): void {
  const rankOf = (row: TodosRow | undefined) => (row === undefined ? null : rankString(String(row["rank"])));
  const moving = rows[index];
  const neighbour = rows[direction === "up" ? index - 1 : index + 1];
  if (moving === undefined || neighbour === undefined) return;
  // Landing between the neighbour and whatever is on its far side.
  const beyond = rows[direction === "up" ? index - 2 : index + 2];
  const [before, after] = direction === "up" ? [beyond, neighbour] : [neighbour, beyond];
  mutators.update(String(moving["id"]), { rank: rankBetween(rankOf(before), rankOf(after), device) });
}
